"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[35434],{3331:(e,a,i)=>{i.d(a,{R:()=>t,x:()=>c});var o=i(36672);const n={},r=o.createContext(n);function t(e){const a=o.useContext(r);return o.useMemo((function(){return"function"==typeof e?e(a):{...a,...e}}),[a,e])}function c(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:t(e.components),o.createElement(r.Provider,{value:a},e.children)}},23676:(e,a,i)=>{i.r(a),i.d(a,{assets:()=>s,contentTitle:()=>c,default:()=>y,frontMatter:()=>t,metadata:()=>o,toc:()=>z});const o=JSON.parse('{"id":"2023/04/16","title":"2023-04-16","description":"Valve ogranicza konta 2500 u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry jako u\u017cyteczn\u0105.","source":"@site/i18n/pl/docusaurus-plugin-content-docs/current/2023/04/16.md","sourceDirName":"2023/04","slug":"/2023/04/16","permalink":"/pl/2023/04/16","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/pl/docusaurus-plugin-content-docs//current/2023/04/16.md","tags":[],"version":"current","frontMatter":{"localized_date":"16 kwietnia 2023","top_news":"Valve ogranicza konta 2500 u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry jako u\u017cyteczn\u0105."},"sidebar":"defaultSidebar","previous":{"title":"2023-04-17","permalink":"/pl/2023/04/17"},"next":{"title":"2023-04-15","permalink":"/pl/2023/04/15"}}');var n=i(23420),r=i(3331);const t={localized_date:"16 kwietnia 2023",top_news:"Valve ogranicza konta 2500 u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry jako u\u017cyteczn\u0105."},c="2023-04-16",s={},z=[{value:"Valve ogranicza konta 2500 u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry jako u\u017cyteczn\u0105.",id:"valve-ogranicza-konta-2500-u\u017cytkownik\xf3w-kt\xf3rzy-zaznaczyli-negatywn\u0105-recenzj\u0119-gry-jako-u\u017cyteczn\u0105",level:2},{value:"Dlaczego kanapka z indykiem w plastikowym opakowaniu kosztuje 15 dolar\xf3w na lotnisku w NYC?",id:"dlaczego-kanapka-z-indykiem-w-plastikowym-opakowaniu-kosztuje-15-dolar\xf3w-na-lotnisku-w-nyc",level:2},{value:"Lofi kontrola ruchu lotniczego - LAX",id:"lofi-kontrola-ruchu-lotniczego---lax",level:2},{value:"Czym s\u0105 modele transformatorowe i jak dzia\u0142aj\u0105?",id:"czym-s\u0105-modele-transformatorowe-i-jak-dzia\u0142aj\u0105",level:2},{value:"Podstawy WebGPU",id:"podstawy-webgpu",level:2},{value:"CEO Google: &quot;czy mo\u017cemy zmieni\u0107 ustawienie tej grupy na history-off&quot; [pdf]",id:"ceo-google-czy-mo\u017cemy-zmieni\u0107-ustawienie-tej-grupy-na-history-off-pdf",level:2},{value:"Surviving Burnout (2015)",id:"surviving-burnout-2015",level:2},{value:"Rozw\xf3j oprogramowania niskokodowego to k\u0142amstwo",id:"rozw\xf3j-oprogramowania-niskokodowego-to-k\u0142amstwo",level:2},{value:"Zdalne wykonanie kodu luka w Google, kt\xf3rej nie chc\u0105 naprawi\u0107",id:"zdalne-wykonanie-kodu-luka-w-google-kt\xf3rej-nie-chc\u0105-naprawi\u0107",level:2},{value:"Rozw\xf3j hiperwizora w Rust",id:"rozw\xf3j-hiperwizora-w-rust",level:2}];function w(e){const a={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(a.header,{children:(0,n.jsx)(a.h1,{id:"2023-04-16",children:"2023-04-16"})}),"\n",(0,n.jsx)(a.h2,{id:"valve-ogranicza-konta-2500-u\u017cytkownik\xf3w-kt\xf3rzy-zaznaczyli-negatywn\u0105-recenzj\u0119-gry-jako-u\u017cyteczn\u0105",children:"Valve ogranicza konta 2500 u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry jako u\u017cyteczn\u0105."}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://tech.slashdot.org/story/23/04/14/175246/valve-restricts-accounts-of-2500-users-who-marked-a-negative-game-review-useful",children:"Original"}),'.\nValve ograniczy\u0142o konta 2500 u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry Warlander jako u\u017cyteczn\u0105, co doprowadzi\u0142o do 30-dniowego zakazu g\u0142osowania w g\xf3r\u0119 i w d\xf3\u0142 dla tych, kt\xf3rych to dotyczy. Moderatorzy Steam sklasyfikowali recenzj\u0119 jako "pr\xf3b\u0119 oszustwa lub inne naruszenie zasad i wytycznych Steam", w wyniku czego recenzja zosta\u0142a usuni\u0119ta, a wielu uwa\u017ca, \u017ce system recenzji jest "ca\u0142kowicie bezcelowy" ze wzgl\u0119du na wp\u0142yw dzia\u0142a\u0144 Valve.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35577895",children:"Discussion Service"}),'.\nValve ogranicza konta u\u017cytkownik\xf3w, kt\xf3rzy zaznaczyli negatywn\u0105 recenzj\u0119 gry jako u\u017cyteczn\u0105, co doprowadzi\u0142o do krytyki ze strony u\u017cytkownik\xf3w Hacker News, \u017ce Valve pozwala na "z\u0142o\u015bliwe oprogramowanie" na swojej platformie. Niekt\xf3rzy sugeruj\u0105 alternatywy dla oprogramowania antycheat, podczas gdy inni twierdz\u0105, \u017ce jest ono niezb\u0119dne, aby zapobiec oszukiwaniu w grach online. W komentarzach dyskutuje si\u0119 o etyce monopolu Steam na dystrybucj\u0119 gier wideo na PC, z r\xf3\u017cnymi opiniami na temat potrzeby monopoli i skuteczno\u015bci oprogramowania anty-cheat.']}),"\n",(0,n.jsx)(a.h2,{id:"dlaczego-kanapka-z-indykiem-w-plastikowym-opakowaniu-kosztuje-15-dolar\xf3w-na-lotnisku-w-nyc",children:"Dlaczego kanapka z indykiem w plastikowym opakowaniu kosztuje 15 dolar\xf3w na lotnisku w NYC?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://hellgatenyc.com/why-is-airport-turkey-sandwich-expensive",children:"Orygina\u0142"}),".\nN/A."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35580847",children:"Discussion Service"}),".\nU\u017cytkownicy Discussion Service debatuj\u0105 nad przyczynami, dla kt\xf3rych kanapka z indykiem w plastikowym opakowaniu kosztuje 15 dolar\xf3w na lotniskach w Nowym Jorku; ograniczona konkurencja na lotniskach i brak mo\u017cliwo\u015bci por\xf3wnania sprzedawc\xf3w F&B uniemo\u017cliwiaj\u0105 zapewnienie uczciwych cen. U\u017cytkownicy sugeruj\u0105, \u017ce pasa\u017cerowie przynosz\u0105 w\u0142asne posi\u0142ki zamiast tego."]}),"\n",(0,n.jsx)(a.h2,{id:"lofi-kontrola-ruchu-lotniczego---lax",children:"Lofi kontrola ruchu lotniczego - LAX"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://www.lofiatc.com/?icao=KLAX",children:"Original"}),".\nPost dzieli si\u0119 cz\u0119stotliwo\u015bci\u0105 wie\u017cy Los Angeles (North) w KLAX, kt\xf3ra wynosi 133,900. Post zawiera teledysk autorstwa Glimlipa x Yaspera i udost\u0119pnia opcj\u0119 przekazania opinii lub darowizny."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35583228",children:"Discussion Service"}),".\nU\u017cytkownicy Hacker News dyskutuj\u0105 o lofiatc.com, nowej aplikacji internetowej, kt\xf3ra \u0142\u0105czy muzyk\u0119 ambientow\u0105 z komunikacj\u0105 kontroli ruchu lotniczego w koj\u0105cy spos\xf3b, wywo\u0142uj\u0105c zainteresowanie; niekt\xf3rzy u\u017cytkownicy prosz\u0105 o dodatkowe funkcje i czat radiowy. U\u017cytkownicy dziel\u0105 si\u0119 r\xf3wnie\u017c swoimi preferencjami dotycz\u0105cymi muzyki ambient podczas pracy, z rekomendacjami dla SomaFM i mynoise.net, a kilka os\xf3b sugeruje czarny metal jako odpowiedni\u0105 alternatyw\u0119, chocia\u017c nie ma wyra\u017anego konsensusu co do najlepszego rodzaju muzyki ambient dla koncentracji."]}),"\n",(0,n.jsx)(a.h2,{id:"czym-s\u0105-modele-transformatorowe-i-jak-dzia\u0142aj\u0105",children:"Czym s\u0105 modele transformatorowe i jak dzia\u0142aj\u0105?"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://txt.cohere.ai/what-are-transformer-models/",children:"Orygina\u0142"}),".\nModele transformacyjne s\u0105 nowym osi\u0105gni\u0119ciem w uczeniu maszynowym i s\u0105 adeptami w generowaniu sp\xf3jnego tekstu poprzez \u015bledzenie kontekstu. Dzi\u0119ki zdolno\u015bci do wykonywania r\xf3\u017cnych zada\u0144, takich jak t\u0142umaczenie mi\u0119dzy j\u0119zykami i odpowiadanie na pytania, transformatory sk\u0142adaj\u0105 si\u0119 z r\xf3\u017cnych komponent\xf3w, w tym tokenizacji, osadzania, kodowania pozycyjnego, blok\xf3w transformacyjnych i softmax. Najbardziej z\u0142o\u017cony blok transformatora wykorzystuje komponenty uwagi i sprz\u0119\u017cenia zwrotnego, przy czym uwaga wielog\u0142owicowa jest u\u017cywana do modyfikacji wektor\xf3w i zapewnienia wi\u0119kszego kontekstu. Po treningu uczy si\u0119 transformator\xf3w wykonywania okre\u015blonych zada\u0144, a ich zdolno\u015b\u0107 do uchwycenia kontekstu przyczyni\u0142a si\u0119 do ich sukcesu."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35576918",children:"Discussion Service"}),".\nU\u017cytkownicy anga\u017cuj\u0105 si\u0119 w dyskusje na temat modeli transformator\xf3w, kwestionuj\u0105c ich skuteczno\u015b\u0107 i kompleksowo\u015b\u0107 tre\u015bci promocyjnych. Wymieniane s\u0105 alternatywne metody tokenizacji, a tak\u017ce polecane s\u0105 zasoby, z kt\xf3rych mo\u017cna dowiedzie\u0107 si\u0119 wi\u0119cej, w tym kursy, filmy i opracowania. Wy\u0142aniaj\u0105ce si\u0119 zachowanie pokazane przez proste modele w sztucznej inteligencji oraz zwi\u0105zek pomi\u0119dzy szczeg\xf3\u0142ami obliczeniowymi a zachowaniem na wysokim poziomie s\u0105 badane, podkre\u015blaj\u0105c aktywny obszar bada\u0144 zwany mechanistyczn\u0105 interpretacj\u0105."]}),"\n",(0,n.jsx)(a.h2,{id:"podstawy-webgpu",children:"Podstawy WebGPU"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://webgpufundamentals.org/",children:"Original"}),".\nTen post dostarcza zestaw artyku\u0142\xf3w do nauki podstaw WebGPU, w tym uk\u0142adu pami\u0119ci danych, matematyki 3D i WebGPU z WebGL. Post zawiera r\xf3wnie\u017c zasoby i referencje do dalszej nauki, jak r\xf3wnie\u017c mo\u017cliwo\u015bci wk\u0142adu. Dzi\u0119kuj\u0119 jrprice za wk\u0142ad."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35579334",children:"Discussion Service"}),".\nWebGPU Fundamentals zyskuje uwag\u0119 na Hacker News jako nast\u0119pca WebGL dla grafiki w przegl\u0105darkach internetowych. U\u017cytkownicy dyskutuj\u0105 o potencjalnych zastosowaniach w symulacji, g\u0142\u0119bokim uczeniu i obawach zwi\u0105zanych z rozrostem funkcji przegl\u0105darki. Komentarze dotycz\u0105 r\xf3wnie\u017c internetowych sekwencer\xf3w MIDI, eksperymentalnych instrument\xf3w i WebUSB do aktualizacji firmware. Niekt\xf3rzy argumentuj\u0105 zalety narz\u0119dzi internetowych, podczas gdy inni wyra\u017caj\u0105 obawy dotycz\u0105ce zagro\u017ce\u0144 bezpiecze\u0144stwa i problem\xf3w z kompatybilno\u015bci\u0105. WebGPU nie ma by\u0107 wysokopoziomowym lub dost\u0119pnym dla pocz\u0105tkuj\u0105cych, ale niskopoziomowym API dla procesor\xf3w graficznych dla do\u015bwiadczonych u\u017cytkownik\xf3w."]}),"\n",(0,n.jsx)(a.h2,{id:"ceo-google-czy-mo\u017cemy-zmieni\u0107-ustawienie-tej-grupy-na-history-off-pdf",children:'CEO Google: "czy mo\u017cemy zmieni\u0107 ustawienie tej grupy na history-off" [pdf]'}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://ia601707.us.archive.org/28/items/gov.uscourts.cand.364454/gov.uscourts.cand.364454.385.0.pdf",children:"Original"}),".\nHacker News omawia WebGPU Fundamentals, nast\u0119pc\u0119 WebGL, pod k\u0105tem jego potencja\u0142u w g\u0142\u0119bokim uczeniu po stronie klienta i symulacjach w przegl\u0105darce. Rozmowy dotykaj\u0105 r\xf3wnie\u017c feature-creep przegl\u0105darki, jej potencjalnej u\u017cyteczno\u015bci i wygody, a tak\u017ce zakresu przegl\u0105darek jako aplikacji lub przegl\u0105darek. Dodatkowo u\u017cytkownicy omawiaj\u0105 sposoby renderowania tekstu za pomoc\u0105 WebGPU, jego kompatybilno\u015b\u0107 z projektami AI oraz trwaj\u0105c\u0105 wsp\xf3\u0142prac\u0119 pomi\u0119dzy zespo\u0142ami WebGPU."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35585174",children:"Discussion Service"}),'.\nDyrektor generalny Google Sundar Pichai staje w obliczu zarzut\xf3w, \u017ce za\u017c\u0105da\u0142 zmiany ustawie\u0144 grupy Google Chat na "wy\u0142\u0105czon\u0105 histori\u0119", pomimo potencjalnych implikacji prawnych i naruszenia FRCP 37(e). U\u017cytkownicy Discussion Service omawiaj\u0105 znaczenie zachowania mo\u017cliwych do odkrycia zapis\xf3w oraz obawy dotycz\u0105ce legalno\u015bci praktyk automatycznego usuwania wiadomo\u015bci, podaj\u0105c przyk\u0142ady innej komunikacji elektronicznej, kt\xf3ra usuwa wiadomo\u015bci. Dodatkowo, dyskusje na temat retencji danych, regulacji rz\u0105dowych i monopoli na ca\u0142ym \u015bwiecie s\u0105 podzielone, podczas gdy obawy dotycz\u0105ce biznesu Google Android i jego braku konkurencji pojawiaj\u0105 si\u0119.']}),"\n",(0,n.jsx)(a.h2,{id:"surviving-burnout-2015",children:"Surviving Burnout (2015)"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://lifeofaudrey.com/essays/surviving_burnout.html",children:"Orygina\u0142"}),".\nWypalenie w bran\u017cy technologicznej jest spowodowane niew\u0142a\u015bciwym roz\u0142o\u017ceniem odpowiedzialno\u015bci, uprawnie\u0144 i zasob\xf3w. Do\u015bwiadczenie autorki z wypaleniem popchn\u0119\u0142o j\u0105 do rzucenia pracy i wej\u015bcia w okres rekonwalescencji, co doprowadzi\u0142o j\u0105 do za\u0142o\u017cenia w\u0142asnej firmy. Wypalenie jest problemem strukturalnym, kt\xf3ry wymaga strukturalnych rozwi\u0105za\u0144, a wsparcie i fundusze na regeneracj\u0119 s\u0105 niezb\u0119dne dla os\xf3b dotkni\u0119tych tym problemem."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35577285",children:"Discussion Service"}),".\nArtyku\u0142 na Hacker News omawia znaczenie znalezienia r\xf3wnowagi, aby unikn\u0105\u0107 wypalenia i utrzyma\u0107 zdrowie psychiczne i fizyczne, podczas gdy u\u017cytkownicy dziel\u0105 si\u0119 osobistymi do\u015bwiadczeniami i oferuj\u0105 porady. Niekt\xf3rzy u\u017cytkownicy Discussion Service podkre\u015blaj\u0105 r\xf3\u017cnice mi\u0119dzy depresj\u0105 a wypaleniem, podczas gdy inni oferuj\u0105 wskaz\xf3wki dotycz\u0105ce radzenia sobie z miejscami pracy powoduj\u0105cymi wypalenie lub rozpocz\u0119cia dzia\u0142alno\u015bci gospodarczej jako potencjalnego rozwi\u0105zania. Kilku czytelnik\xf3w dyskutuje r\xf3wnie\u017c o skuteczno\u015bci korzystania z us\u0142ug trenera stylu \u017cycia lub terapeuty w walce z wypaleniem zawodowym. Ostatecznie, najwa\u017cniejszy wniosek jest taki, \u017ce dbanie o prac\u0119 jest wa\u017cne, ale nie kosztem w\u0142asnego samopoczucia."]}),"\n",(0,n.jsx)(a.h2,{id:"rozw\xf3j-oprogramowania-niskokodowego-to-k\u0142amstwo",children:"Rozw\xf3j oprogramowania niskokodowego to k\u0142amstwo"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://jaylittle.com/post/view/2023/4/low-code-software-development-is-a-lie",children:"Original"}),'.\nDo\u015bwiadczony programista przekonuje, \u017ce tworzenie oprogramowania jest trudne z powodu niezrozumienia przez klient\xf3w i programist\xf3w podstawowych przyczyn problem\xf3w, kt\xf3re chc\u0105 rozwi\u0105za\u0107, a nie z winy j\u0119zyk\xf3w i narz\u0119dzi kodowania. Autor krytykuje ide\u0119 narz\u0119dzi "niskiego kodu", takich jak OutSystems, stwierdzaj\u0105c, \u017ce nie usuwaj\u0105 one nieod\u0142\u0105cznej z\u0142o\u017cono\u015bci i mog\u0105 prowadzi\u0107 do s\u0142abo przemy\u015blanych system\xf3w oprogramowania, a tak\u017ce s\u0105 drogie i wi\u0105\u017c\u0105 si\u0119 z uzale\u017cnieniem od dostawcy. W\u0142a\u015bciwe zaprojektowanie rozwi\u0105zania jest najtrudniejsz\u0105 cz\u0119\u015bci\u0105 procesu tworzenia oprogramowania i \u017cadne narz\u0119dzie nie zast\u0105pi niezb\u0119dnego my\u015blenia, dyskusji i planowania.']}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35578240",children:"Discussion Service"}),".\nTworzenie oprogramowania o niskim kodzie jest przydatne w przypadku prostszych problem\xf3w, ale nie nadaje si\u0119 do z\u0142o\u017conych i nie powinno ca\u0142kowicie zast\u0105pi\u0107 programist\xf3w. Komentarze Discussion Service omawiaj\u0105 ograniczenia i kompromisy platform o niskim kodzie, w\u0142\u0105czaj\u0105c w to s\u0142abe narz\u0119dzia do testowania, wersjonowania i debugowania, kt\xf3re mog\u0105 prowadzi\u0107 do uzale\u017cnienia od dostawcy. Niekt\xf3rzy eksperci sugeruj\u0105, \u017ce narz\u0119dzia low-code mog\u0105 by\u0107 warto\u015bciowe dla prototyp\xf3w i niekt\xf3rych zastosowa\u0144, ale inni przestrzegaj\u0105 przed nadmiernym poleganiem na nich i zalecaj\u0105 staranny wyb\xf3r odpowiednich narz\u0119dzi. Podczas gdy low-code ma r\xf3\u017cne przypadki u\u017cycia, definicja jest nieostra i potencjalnie myl\u0105ca, a przyk\u0142adami s\u0105 Excel i wykresy shader\xf3w."]}),"\n",(0,n.jsx)(a.h2,{id:"zdalne-wykonanie-kodu-luka-w-google-kt\xf3rej-nie-chc\u0105-naprawi\u0107",children:"Zdalne wykonanie kodu luka w Google, kt\xf3rej nie chc\u0105 naprawi\u0107"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://giraffesecurity.dev/posts/google-remote-code-execution/",children:"Original"}),".\nBadacz bezpiecze\u0144stwa znalaz\u0142 luk\u0119 w Google, kt\xf3ra pozwala\u0142a im na uruchomienie dowolnego kodu na komputerach ponad 50 pracownik\xf3w Google, spowodowan\u0105 zamieszaniem zale\u017cno\u015bci w systemie zarz\u0105dzania Pythonem. Google pocz\u0105tkowo sklasyfikowa\u0142 j\u0105 jako powa\u017cn\u0105, ale p\xf3\u017aniej zmieni\u0142 j\u0105 na zamierzone zachowanie. Badacz obawia si\u0119, \u017ce luka mo\u017ce zosta\u0107 wykorzystana, poniewa\u017c codziennie otrzymuje \u015bci\u0105gni\u0119te pliki od pracownik\xf3w Google i podejrzewa, \u017ce Google nie rozumie problemu, lub nie zale\u017cy im na jego naprawie."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35581532",children:"Discussion Service"}),".\nLuka Remote Code Execution (RCE) znaleziona w oprogramowaniu Google podobno nie jest naprawiana, przy czym niekt\xf3rzy u\u017cytkownicy wskazuj\u0105, \u017ce system zarz\u0105dzania pakietami Javy ma bezpieczniejszy spos\xf3b wgrywania pakiet\xf3w ni\u017c system Rusta, podczas gdy inni sugeruj\u0105, \u017ce ",(0,n.jsx)(a.code,{children:"pip install --extra-index-url"}),' ignoruje rejestry specyficzne dla u\u017cytkownika, czyni\u0105c prywatne rejestry bezu\u017cytecznymi. Google stosuje \u015brodki bezpiecze\u0144stwa typu "zero zaufania", aby zwalcza\u0107 zagro\u017cenia wewn\u0119trzne, ale APT mo\u017ce wykorzysta\u0107 t\u0119 luk\u0119 do zdobycia przycz\xf3\u0142ka w \u015brodowisku. Podkre\u015blono r\xf3wnie\u017c potrzeb\u0119 lepszych rozwi\u0105za\u0144 do zarz\u0105dzania pakietami oraz rol\u0119 zero-trust w zapobieganiu takim atakom.']}),"\n",(0,n.jsx)(a.h2,{id:"rozw\xf3j-hiperwizora-w-rust",children:"Rozw\xf3j hiperwizora w Rust"}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"https://memn0ps.github.io/hypervisor-development-in-rust-part-1/",children:"Original"}),".\nTen artyku\u0142 opisuje rozw\xf3j hiperwizora badawczego opartego na Rust dla wirtualizacji Intel VT-x, dostarczaj\u0105c przyk\u0142ady kodu Rust dla obs\u0142ugi VMX i omawiaj\u0105c proces inicjalizacji region\xf3w pami\u0119ci dla wirtualnych procesor\xf3w. Ma on na celu bycie u\u017cytecznym zasobem dla ekspert\xf3w w dziedzinie wirtualizacji z wykorzystaniem Rust. Artyku\u0142 zachowuje neutralno\u015b\u0107 i zapewnia referencje i kredyty."]}),"\n",(0,n.jsxs)(a.p,{children:[(0,n.jsx)(a.a,{href:"http://news.ycombinator.com/item?id=35579876",children:"Discussion Service"}),".\nU\u017cytkownik Hacker News komentuje artyku\u0142 o wirtualizacji procesora i wyra\u017ca zainteresowanie wirtualizacj\u0105 urz\u0105dze\u0144, podkre\u015blaj\u0105c stoj\u0105ce przed ni\u0105 wyzwania i proponuj\u0105c nowe rozwi\u0105zania. Inni u\u017cytkownicy podaj\u0105 zasoby i alternatywy dla u\u017cytkownik\xf3w Linuksa zainteresowanych t\u0105 dziedzin\u0105."]})]})}function y(e={}){const{wrapper:a}={...(0,r.R)(),...e.components};return a?(0,n.jsx)(a,{...e,children:(0,n.jsx)(w,{...e})}):w(e)}}}]);